import { instantToHHMM, type LineInput, type LogLine, type LogWithLines } from '@motivation/shared';
import { HealthService } from '../../../services/health.service.js';
import { getAppTimeZone } from '../../../services/app-timezone.service.js';
import { goBack, navigate } from '../../../router.js';
import { buildSectionPage } from '../../../utils/section-page.utils.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { safeExec } from '../../../utils/safe-exec.js';
import { logLineView, toLineInput, withAmount } from '../../../utils/line-view.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';
import { HEALTH_EVENTS, type LineEditorRemoveEvent, type LineEditorSaveEvent } from '../health-events.js';
import { dayPath } from '../health-log-edit-screen/health-log-edit-screen.component.js';
import '../nutrition/line-editor/line-editor.component.js';
import type { LineEditor } from '../nutrition/line-editor/line-editor.component.js';
import themeStyles from '../health-theme.css?inline';
import screenStyles from '../health-log-new-screen/health-log-new-screen.css?inline';

documentStyleSheet(themeStyles);
documentStyleSheet(screenStyles);

/**
 * Story 422 (418 #9) — one logged line (`/health/log/:id/line/:lineId`): `<line-editor>` with the
 * amount, presets and the per-line nutrition override (story 368). Done sends the log's complete
 * list with this line changed (`PUT /lines`); Remove takes the line out — the log with it, when
 * it was the only one. "Edit the log" opens the whole log, for a one-line log's day, slot or time.
 */
export class HealthLineEditScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private logIdValue = '';
    private lineIdValue = '';
    private readonly body = document.createElement('div');
    private readonly log = createComponentLogger('health-line-edit-screen');
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    set logId(value: string) { this.logIdValue = value; }
    set lineId(value: string) { this.lineIdValue = value; }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;
        const page = buildSectionPage(this, 'Edit line', 'health', '/health');
        this.body.className = 'log-edit';
        this.statusNodes.retryNode.addEventListener('click', () => void this.load());
        page.content.append(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode, this.body);
        void this.load();
    }

    private async load(): Promise<void> {
        return safeExec(this, this.log, async () => {
            const log = await HealthService.findLog(this.logIdValue);
            if (!log) throw new Error(`Log ${this.logIdValue} not found.`);
            const line = log.lines.find((l) => l.id === this.lineIdValue);
            if (!line) throw new Error(`Line ${this.lineIdValue} is not in log ${log.id}.`);
            this.render(log, line);
        });
    }

    private render(log: LogWithLines, line: LogLine): void {
        const lineId = line.id;
        const view = logLineView(line);

        const title = document.createElement('h2');
        title.className = 'line-title';
        title.textContent = line.food_name;
        const context = document.createElement('p');
        context.className = 'line-context';
        const time = log.consumed_at ? ` ${instantToHHMM(log.consumed_at, getAppTimeZone())}` : '';
        context.textContent = log.lines.length > 1 && log.name
            ? `In ${log.name} · ${log.meal_type}${time} · ${log.date}`
            : `${log.meal_type}${time} · ${log.date}`;

        const editor = document.createElement('line-editor') as LineEditor;
        editor.setAttribute('removable', '');
        customElements.upgrade(editor);
        editor.line = view;
        editor.addEventListener(HEALTH_EVENTS.LINE_EDITOR_SAVE, (e: LineEditorSaveEvent) => {
            const { override: _old, ...rest } = withAmount(view, e.detail.amount);
            const edited = toLineInput(e.detail.override ? { ...rest, override: e.detail.override } : rest);
            e.detail.respondWith = this.write(log, log.lines.map((l): LineInput => (l.id === lineId ? edited : { id: l.id, amount: l.amount })));
        });
        editor.addEventListener(HEALTH_EVENTS.LINE_EDITOR_REMOVE, (e: LineEditorRemoveEvent) => {
            const rest = log.lines.filter((l) => l.id !== lineId).map((l): LineInput => ({ id: l.id, amount: l.amount }));
            e.detail.respondWith = this.write(log, rest);
        });

        const editLog = document.createElement('button');
        editLog.type = 'button';
        editLog.className = 'edit-log-link';
        editLog.textContent = 'Edit the log…';
        editLog.addEventListener('click', () => navigate(`/health/log/${encodeURIComponent(log.id)}`));

        this.body.replaceChildren(title, context, editor, editLog);
    }

    /** The log's complete list (story 311's semantics); no lines left is no log left. */
    private async write(log: LogWithLines, lines: LineInput[]): Promise<void> {
        return safeExec(this, this.log, async () => {
            if (lines.length === 0) await HealthService.deleteLog(log.id);
            else await HealthService.replaceLogLines(log.id, lines);
            goBack(dayPath(log.date));
        });
    }
}

if (!customElements.get('health-line-edit-screen')) {
    customElements.define('health-line-edit-screen', HealthLineEditScreen);
}
